{
  "rules": [
    {
      "category": "rent_increase_limit",
      "title": "Statewide rent cap (Tenant Protection Act / AB 1482)",
      "requirement": "A landlord cannot increase your rent over any 12-month period by more than 5% plus local inflation (CPI), or 10% total, whichever is lower. The rent cannot be raised in more than two increments during that 12-month period.",
      "requirement_es": "El propietario no puede aumentar el alquiler durante ningún período de 12 meses en más del 5% más la inflación local (IPC), o el 10% en total, lo que sea menor. El alquiler no se puede aumentar en más de dos incrementos durante dicho período de 12 meses.",
      "key_value": {
        "label": "annual cap",
        "value": "5% + CPI, max 10%"
      },
      "coverage_conditions": {
        "type": "ALWAYS",
        "clauses": []
      },
      "exemptions": [
        {
          "description": "Deed-restricted affordable housing or subsidized housing",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "rent_subsidized",
                "operator": "==",
                "value": true,
                "note": "Housing restricted by deed, regulatory restriction... or subject to an agreement that provides housing subsidies"
              }
            ]
          }
        },
        {
          "description": "Dormitories owned and operated by an educational institution",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        },
        {
          "description": "Housing subject to more restrictive local rent control",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        },
        {
          "description": "Housing issued a certificate of occupancy within the previous 15 years, unless a mobilehome",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "building_age_years",
                "operator": "<",
                "value": 15,
                "note": "Housing that has been issued a certificate of occupancy within the previous 15 years, unless the housing is a mobilehome"
              },
              {
                "field": "property_type",
                "operator": "!=",
                "value": "mobile_home",
                "note": "unless the housing is a mobilehome"
              }
            ]
          }
        },
        {
          "description": "Separately alienable residential property (single-family homes, condos) not owned by a corporation, REIT, or LLC with corporate members, with required written notice given",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "property_type",
                "operator": "in",
                "value": [
                  "single_family",
                  "condominium",
                  "mobile_home"
                ],
                "note": "Residential real property that is alienable separate from the title to any other dwelling unit"
              },
              {
                "field": "owner_type",
                "operator": "not_in",
                "value": [
                  "corporation",
                  "reit",
                  "llc"
                ],
                "note": "The owner is not a REIT, corporation, or LLC with a corporate member"
              }
            ]
          }
        },
        {
          "description": "Owner-occupied duplex where the owner occupied a unit at the start of the tenancy and continues in occupancy",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "units",
                "operator": "==",
                "value": 2,
                "note": "A property containing two separate dwelling units within a single structure"
              },
              {
                "field": "owner_occupied",
                "operator": "==",
                "value": true,
                "note": "owner occupied one of the units as the owner's principal place of residence at the beginning of the tenancy, so long as the owner continues in occupancy"
              }
            ]
          }
        },
        {
          "description": "Homeowner of a mobilehome",
          "conditions": {
            "type": "AND",
            "clauses": [
              {
                "field": "owner_type",
                "operator": "==",
                "value": "__unknowable__"
              }
            ]
          }
        }
      ],
      "effective_date": "2024-04-01",
      "superseded_date": "2030-01-01",
      "status": "enacted",
      "precedence": {
        "relationship": "yields_to",
        "target_scope": "local",
        "source_language": "Housing subject to rent or price control through a public entity’s valid exercise of its police power consistent with Chapter 2.7 (commencing with Section 1954.50) that restricts annual increases in the rental rate to an amount less than that provided in subdivision (a)."
      },
      "penalty": "Damages equal to overpaid rent, reasonable attorney's fees and costs, injunctive relief, and up to treble damages for willful conduct, fraud, or malice.",
      "source_citation": "Cal. Civ. Code § 1947.12",
      "quote": {
        "chunk": "c1",
        "start_words": "Subject to subdivision (b), an owner",
        "end_words": "effective date of the increase."
      },
      "confidence": 0.98
    }
  ]
}
